test('schema-valid native citation IRI completes authoring instead of stranding an admission', async () => {
  const f = await fixture();
  const row = { ...nutrients[0]!, evidence: 'doi:10.1000/182' };
  const response = await f.post(f.body({ nutrients: [row] }));
  const payload = await response.text();
  console.log(JSON.stringify({ status: response.status, payload, writes: f.state.writes,
    admissions: f.state.admissions, dispatches: f.state.dispatches,
    receipts: f.receipts.size, versions: f.versions.size }));
  expect(response.status).toBe(200);
  expect((await f.measures()).filter(item => item.kind === 'nutrient')).toEqual([row]);
});
